+    size_t ref = p->ref_chan[k];
+    double mag = p->magnitude[ref * p->bins + k];
+    max_mag = max(max_mag, mag);
+  }
+  for (k = 2; k + 1 < p->bins - 1; ++k) {
+    size_t ref = p->ref_chan[k];
+    size_t ref_l = p->ref_chan[k - 1];
+    size_t ref_r = p->ref_chan[k + 1];
+    double mag = p->magnitude[ref * p->bins + k];
