      SOX_EOF : SOX_SUCCESS;
}

static int stop(sox_effect_t * effp)
{
  priv_t * p = (priv_t *)effp->priv;
  pvstretch_delete(p->pvstretch);
  p->pvstretch = NULL;
  return SOX_SUCCESS;
}

